#include <bits/stdc++.h>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;    while (t--) {        int n, m;        long long h;        cin >> n >> m >> h;         vector<long long> orig(n);        for (int i = 0; i < n; i++) cin >> orig[i];         vector<long long> add(n, 0);        vector<int> last(n, 0);         int curVersion = 1;         while (m--) {            int b;            long long c;            cin >> b >> c;            b--;             if (last[b] != curVersion) {                last[b] = curVersion;                add[b] = 0;            }             add[b] += c;             if (orig[b] + add[b] > h) {                curVersion++;             }        }         for (int i = 0; i < n; i++) {            if (last[i] != curVersion) add[i] = 0;            cout << orig[i] + add[i] << " ";        }        cout << "\n";    }    return 0;}